sys_script.script:
(function executeRule(current, previous) {
    var newType = current.getValue('contract_type');
    var oldType = previous.getValue('contract_type');

    if (newType === oldType) {
        return;
    }

    // Map contract types to their type-specific tables
    var typeTableMap = {
        'cpff': 'x_942105_costima_0_cpff_fee',
        'tm': 'x_942105_costima_0_tm_rate',
        'ffp': 'x_942105_costima_0_ffp_clin'
    };

    var typeLabels = {
        'cpff': 'CPFF',
        'tm': 'T&M',
        'ffp': 'FFP'
    };

    var proposalId = current.getUniqueValue();
    var orphanedData = [];

    // Check ALL type-specific tables for data tied to this proposal
    for (var type in typeTableMap) {
        var tableName = typeTableMap[type];
        var gr = new GlideRecord(tableName);
        if (gr.isValid()) {
            gr.addQuery('proposal', proposalId);
            gr.query();
            var count = gr.getRowCount();
            if (count > 0) {
                orphanedData.push(typeLabels[type] + ' (' + count + ' record' + (count > 1 ? 's' : '') + ' in ' + tableName + ')');
            }
        }
    }

    if (orphanedData.length === 0) {
        return; // No data to protect
    }

    // Check if user has admin role
    if (gs.hasRole('x_942105_costima_0.admin')) {
        // Admin override — allow but warn
        gs.addInfoMessage(
            'WARNING: Changing contract type from ' + typeLabels[oldType] + ' to ' + typeLabels[newType] +
            '. The following data will become orphaned: ' + orphanedData.join('; ') +
            '. Review and clean up affected records.'
        );
        return; // Allow the change
    }

    // Non-admin — block the change
    gs.addErrorMessage(
        'Cannot change contract type from ' + typeLabels[oldType] + ' to ' + typeLabels[newType] +
        '. Existing cost data would become orphaned: ' + orphanedData.join('; ') +
        '. Contact a Costimator administrator to override.'
    );
    current.setAbortAction(true);
})(current, previous);
